static mrb_int
chars2bytes(mrb_value s, mrb_int off, mrb_int idx)
{
mrb_int i, b, n;
const char *p = RSTRING_PTR(s) + off;
const char *e = RSTRING_END(s);

for (b=i=0; p<e && i<idx; i++) {
n = utf8len(p, e);
b += n;
p += n;
}
return b;
}


static mrb_int
bytes2chars(char *p, mrb_int bi)
{
mrb_int i, b, n;

for (b=i=0; b<bi; i++) {
n = utf8len_codepage[(unsigned char)*p];
b += n;
p += n;
}
if (b != bi) return -1;
return i;
}

