switch (c) {
case '"': case '\\':
case '\n': case '\r':
case '\t': case '\f':
case '\013': case '\010': case '\007': case '\033':
len += 2;
break;

case '#':
len += IS_EVSTR(p, pend) ? 2 : 1;
break;

default:
if (ISPRINT(c)) {
len++;
}
else {
len += 4;
}
break;
}
}

result = str_new(mrb, 0, len);
str_with_class(mrb, result, str);
p = RSTRING_PTR(str); pend = p + RSTRING_LEN(str);
q = RSTR_PTR(result);
*q++ = '"';
while (p < pend) {
unsigned char c = *p++;

switch (c) {
case '"':
case '\\':
*q++ = '\\';
*q++ = c;
break;

case '\n':
*q++ = '\\';
*q++ = 'n';
break;

case '\r':
*q++ = '\\';
*q++ = 'r';
break;

case '\t':
*q++ = '\\';
*q++ = 't';
break;

case '\f':
*q++ = '\\';
*q++ = 'f';
break;

case '\013':
*q++ = '\\';
*q++ = 'v';
break;

case '\010':
*q++ = '\\';
*q++ = 'b';
break;

case '\007':
*q++ = '\\';
*q++ = 'a';
break;

case '\033':
*q++ = '\\';
*q++ = 'e';
break;

case '#':
if (IS_EVSTR(p, pend)) *q++ = '\\';
*q++ = '#';
break;

default:
if (ISPRINT(c)) {
*q++ = c;
}
else {
*q++ = '\\';
*q++ = 'x';
