static char*
remove_sign_bits(char *str, int base)
{
char *t;

t = str;
if (base == 16) {
while (*t == 'f') {
t++;
}
}
else if (base == 8) {
*t |= EXTENDSIGN(3, strlen(t));
while (*t == '7') {
t++;
}
}
else if (base == 2) {
while (*t == '1') {
t++;
}
}

return t;
}

static char
sign_bits(int base, const char *p)
{
char c;

switch (base) {
case 16:
if (*p == 'X') c = 'F';
else c = 'f';
break;
case 8:
c = '7'; break;
case 2:
c = '1'; break;
default:
c = '.'; break;
}
return c;
}

