#ifndef MRB_WITHOUT_FLOAT
static void
fmt_setup(char *buf, size_t size, int c, int flags, mrb_int width, mrb_int prec)
{
char *end = buf + size;
int n;

*buf++ = '%';
if (flags & FSHARP) *buf++ = '#';
if (flags & FPLUS) *buf++ = '+';
if (flags & FMINUS) *buf++ = '-';
if (flags & FZERO) *buf++ = '0';
if (flags & FSPACE) *buf++ = ' ';

if (flags & FWIDTH) {
n = snprintf(buf, end - buf, "%d", (int)width);
buf += n;
}

if (flags & FPREC) {
n = snprintf(buf, end - buf, ".%d", (int)prec);
buf += n;
}

*buf++ = c;
*buf = '\0';
}
#endif


