static void
to_binary(unsigned int v, char s[])
{
unsigned int mask;
int i;

mask = 1 << (sizeof(v) * 8 - 1);
i = 0;
do {
s[i++] = (mask & v ? '1' : '0');
} while (mask >>= 1);
s[i] = 0;
}
