static void
dump_data(FILE* fp, unsigned char* data, int len)
{
int i;

fprintf(fp, "{\n");
for (i = 0; i < len; i++) {
unsigned char c = data[i];

if (isprint((int )c)) {
if (c == '\\')
fprintf(fp, " '\\\\'");
else
fprintf(fp, " '%c'", c);
}
else {
fprintf(fp, "0x%02x", (int )c);
}

if (i == len - 1) {
fprintf(fp, "\n");
}
else {
if (i % 8 == 7)
fprintf(fp, ",\n");
else
fprintf(fp, ", ");
}
}
fprintf(fp, "};\n");
}

