}

if (i == 0 && feof(stdin)) {
clearerr(stdin);
strcpy(mrdb->command, "quit");
i += sizeof("quit") - 1;
}

if (i == MAX_COMMAND_LINE) {
for ( ; (c=getchar()) != EOF && c !='\n'; i++) ;
}

if (i > MAX_COMMAND_LINE) {
printf("command line too long.\n");
i = 0;
}
mrdb->command[i] = '\0';

