break;
}
}

static debug_command*
get_and_parse_command(mrb_state *mrb, mrdb_state *mrdb)
{
debug_command *cmd = NULL;
char *p;
int i;

while (!cmd) {
for (p=NULL; !p || *p=='\0'; ) {
printf("(%s:%d) ", mrdb->dbg->prvfile, mrdb->dbg->prvline);
fflush(stdout);
