static char*
pick_out_word(mrb_state *mrb, char **pp)
{
char *ps;

for (ps=*pp; ISBLANK(*ps); ps++) ;
if (*ps == '\0') {
return NULL;
}

if (*ps == '\"' || *ps == '\'') {
*pp = strchr(ps+1, *ps);
if (*pp) (*pp)++;
}
else {
*pp = strpbrk(ps, " \t");
}

if (!*pp) {
*pp = ps + strlen(ps);
}

if (**pp != '\0') {
**pp = '\0';
(*pp)++;
}

return ps;
}

static debug_command*
