data++;
remaining_size--;

lead_num = data[0];
data++;
remaining_size--;
lead = (lead_num % 2 == 0 ? ONIG_REGSET_POSITION_LEAD : ONIG_REGSET_REGEX_LEAD);

if (remaining_size < reg_num * 2) {
reg_num = reg_num % 15;
}

init_reg_num %= (reg_num + 1);

if (MaxRegNum < reg_num)
MaxRegNum = reg_num;

if (MaxInitRegNum < init_reg_num)
MaxInitRegNum = init_reg_num;

if (reg_num == 0)
pattern_size = 1;
