extern int main(int argc, char* argv[])
{
size_t n;
uint8_t Data[10000];

n = read(0, Data, sizeof(Data));
fprintf(stdout, "n: %ld\n", n);
LLVMFuzzerTestOneInput(Data, n);

return 0;
}
#endif


