*b = mrb_digitmap[-(n % base)];
} while (n /= base);
if (b-- == buf) return NULL;
*b = '-';
}
else {
do {
if (b-- == buf) return NULL;
*b = mrb_digitmap[(int)(n % base)];
} while (n /= base);
}
return b;
}

