t = (htable*)mrb_malloc(mrb, sizeof(htable));
t->size = 0;
t->rootseg = NULL;
t->lastseg = NULL;
t->last_len = 0;
t->index = NULL;

return t;
}

#define power2(v) do { \
v--;\
v |= v >> 1;\
v |= v >> 2;\
v |= v >> 4;\
v |= v >> 8;\
v |= v >> 16;\
v++;\
} while (0)

#ifndef UPPER_BOUND
#define UPPER_BOUND(x) ((x)>>2|(x)>>1)
#endif

#define HT_MASK(index) ((index->capa)-1)


static void
ht_index(mrb_state *mrb, htable *t)
{
size_t size = (size_t)t->size;
size_t mask;
segindex *index = t->index;
segment *seg;
size_t i;


if (index && index->size >= UPPER_BOUND(index->capa)) {
size = index->capa+1;
}
power2(size);
if (!index || index->capa < size) {
index = (segindex*)mrb_realloc_simple(mrb, index, sizeof(segindex)+sizeof(struct segkv*)*size);
if (index == NULL) {
mrb_free(mrb, t->index);
t->index = NULL;
return;
}
t->index = index;
}
index->size = t->size;
index->capa = size;
for (i=0; i<size; i++) {
index->table[i] = NULL;
}


mask = HT_MASK(index);
seg = t->rootseg;
while (seg) {
for (i=0; i<seg->size; i++) {
mrb_value key;
size_t k, step = 0;

if (!seg->next && i >= (size_t)t->last_len) {
return;
}
key = seg->e[i].key;
if (mrb_undef_p(key)) continue;
k = ht_hash_func(mrb, t, key) & mask;
while (index->table[k]) {
k = (k+(++step)) & mask;
}
index->table[k] = &seg->e[i];
}
seg = seg->next;
}
}


static void
ht_compact(mrb_state *mrb, htable *t)
{
segment *seg;
mrb_int i;
segment *seg2 = NULL;
mrb_int i2;
mrb_int size = 0;

if (t == NULL) return;
seg = t->rootseg;
if (t->index && (size_t)t->size == t->index->size) {
ht_index(mrb, t);
return;
}
while (seg) {
for (i=0; i<seg->size; i++) {
mrb_value k = seg->e[i].key;

if (!seg->next && i >= t->last_len) {
goto exit;
}
if (mrb_undef_p(k)) {
if (seg2 == NULL) {
seg2 = seg;
i2 = i;
}
}
else {
size++;
if (seg2 != NULL) {
seg2->e[i2++] = seg->e[i];
if (i2 >= seg2->size) {
seg2 = seg2->next;
i2 = 0;
}
}
}
}
seg = seg->next;
}
exit:

t->size = size;
if (seg2) {
seg = seg2->next;
seg2->next = NULL;
t->last_len = i2;
t->lastseg = seg2;
while (seg) {
seg2 = seg->next;
mrb_free(mrb, seg);
seg = seg2;
}
}
if (t->index) {
ht_index(mrb, t);
}
}

static segment*
segment_alloc(mrb_state *mrb, segment *seg)
{
uint32_t size;

if (!seg) size = MRB_HT_INIT_SIZE;
else {
size = seg->size*HT_SEG_INCREASE_RATIO + 1;
if (size > UINT16_MAX) size = UINT16_MAX;
}

seg = (segment*)mrb_malloc(mrb, sizeof(segment)+sizeof(struct segkv)*size);
seg->size = size;
seg->next = NULL;

return seg;
}


static void
ht_index_put(mrb_state *mrb, htable *t, mrb_value key, mrb_value val)
{
segindex *index = t->index;
size_t k, sp, step = 0, mask;
segment *seg;

if (index->size >= UPPER_BOUND(index->capa)) {

ht_compact(mrb, t);
index = t->index;
}
mask = HT_MASK(index);
sp = index->capa;
k = ht_hash_func(mrb, t, key) & mask;
while (index->table[k]) {
mrb_value key2 = index->table[k]->key;
if (mrb_undef_p(key2)) {
if (sp == index->capa) sp = k;
}
else if (ht_hash_equal(mrb, t, key, key2)) {
index->table[k]->val = val;
return;
}
k = (k+(++step)) & mask;
}
if (sp < index->capa) {
k = sp;
}


seg = t->lastseg;
if (t->last_len < seg->size) {
index->table[k] = &seg->e[t->last_len++];
}
else {
seg->next = segment_alloc(mrb, seg);
seg = seg->next;
seg->next = NULL;
t->lastseg = seg;
t->last_len = 1;
index->table[k] = &seg->e[0];
}
index->table[k]->key = key;
index->table[k]->val = val;
index->size++;
t->size++;
}


static void
ht_put(mrb_state *mrb, htable *t, mrb_value key, mrb_value val)
{
segment *seg;
mrb_int i, deleted = 0;

if (t == NULL) return;
if (t->index) {
ht_index_put(mrb, t, key, val);
return;
}
seg = t->rootseg;
while (seg) {
for (i=0; i<seg->size; i++) {
mrb_value k = seg->e[i].key;

if (!seg->next && i >= t->last_len) {
seg->e[i].key = key;
seg->e[i].val = val;
t->last_len = i+1;
t->size++;
return;
}
if (mrb_undef_p(k)) {
deleted++;
continue;
}
if (ht_hash_equal(mrb, t, k, key)) {
seg->e[i].val = val;
return;
}
}
seg = seg->next;
}



if (deleted > 0 && deleted > MRB_HT_INIT_SIZE) {
ht_compact(mrb, t);
}
t->size++;


if (t->lastseg && t->last_len < t->lastseg->size) {
seg = t->lastseg;
i = t->last_len;
}
else {

seg = segment_alloc(mrb, t->lastseg);
i = 0;
if (t->rootseg == NULL) {
t->rootseg = seg;
}
else {
t->lastseg->next = seg;
}
t->lastseg = seg;
}
seg->e[i].key = key;
seg->e[i].val = val;
t->last_len = i+1;
if (t->index == NULL && t->size > MRB_HT_INIT_SIZE*4) {
ht_index(mrb, t);
}
}


static mrb_bool
ht_index_get(mrb_state *mrb, htable *t, mrb_value key, mrb_value *vp)
{
segindex *index = t->index;
size_t mask = HT_MASK(index);
size_t k = ht_hash_func(mrb, t, key) & mask;
size_t step = 0;

while (index->table[k]) {
mrb_value key2 = index->table[k]->key;
if (!mrb_undef_p(key2) && ht_hash_equal(mrb, t, key, key2)) {
if (vp) *vp = index->table[k]->val;
return TRUE;
}
k = (k+(++step)) & mask;
}
return FALSE;
}


static mrb_bool
ht_get(mrb_state *mrb, htable *t, mrb_value key, mrb_value *vp)
{
segment *seg;
mrb_int i;

if (t == NULL) return FALSE;
if (t->index) {
return ht_index_get(mrb, t, key, vp);
}

seg = t->rootseg;
while (seg) {
for (i=0; i<seg->size; i++) {
mrb_value k = seg->e[i].key;

if (!seg->next && i >= t->last_len) {
return FALSE;
}
if (mrb_undef_p(k)) continue;
if (ht_hash_equal(mrb, t, k, key)) {
if (vp) *vp = seg->e[i].val;
return TRUE;
}
}
seg = seg->next;
}
return FALSE;
}



static mrb_bool
ht_del(mrb_state *mrb, htable *t, mrb_value key, mrb_value *vp)
{
segment *seg;
mrb_int i;

if (t == NULL) return FALSE;
seg = t->rootseg;
while (seg) {
for (i=0; i<seg->size; i++) {
mrb_value key2;

if (!seg->next && i >= t->last_len) {

return FALSE;
}
key2 = seg->e[i].key;
if (!mrb_undef_p(key2) && ht_hash_equal(mrb, t, key, key2)) {
if (vp) *vp = seg->e[i].val;
seg->e[i].key = mrb_undef_value();
t->size--;
return TRUE;
}
}
seg = seg->next;
}
return FALSE;
}


static void
ht_foreach(mrb_state *mrb, htable *t, mrb_hash_foreach_func *func, void *p)
{
segment *seg;
mrb_int i;

if (t == NULL) return;
seg = t->rootseg;
while (seg) {
for (i=0; i<seg->size; i++) {

if (!seg->next && i >= t->last_len) {
return;
