static htable*
ht_copy(mrb_state *mrb, htable *t)
{
segment *seg;
htable *t2;
mrb_int i;

seg = t->rootseg;
t2 = ht_new(mrb);
if (t->size == 0) return t2;

while (seg) {
for (i=0; i<seg->size; i++) {
mrb_value key = seg->e[i].key;
mrb_value val = seg->e[i].val;

if (mrb_undef_p(key)) continue;
if ((seg->next == NULL) && (i >= t->last_len)) {
return t2;
}
ht_put(mrb, t2, key, val);
}
seg = seg->next;
}
return t2;
}


static void
ht_free(mrb_state *mrb, htable *t)
{
segment *seg;

if (!t) return;
seg = t->rootseg;
while (seg) {
segment *p = seg;
seg = seg->next;
mrb_free(mrb, p);
}
if (t->index) mrb_free(mrb, t->index);
mrb_free(mrb, t);
}

