}
key = seg->e[i].key;
if (mrb_undef_p(key)) continue;
*kp = key;
*vp = seg->e[i].val;

seg->e[i].key = mrb_undef_value();
t->size--;
return;
}
seg = seg->next;
}
}


/*
* call-seq:
* hsh.shift -> anArray or obj
