c = intn(p->pb->car);
tmp = p->pb;
p->pb = p->pb->cdr;
cons_free(tmp);
}
else {
c = nextc0(p);
if (c < 0) goto eof;
}
if (c >= 0) {
p->column++;
}
if (c == '\r') {
const int lf = nextc0(p);
if (lf == '\n') {
return '\n';
}
if (lf > 0) pushback(p, lf);
}
return c;

eof:
if (!p->cxt) return -1;
else {
if (p->cxt->partial_hook(p) < 0)
