static int
peekc_n(parser_state *p, int n)
{
node *list = 0;
int c0;

do {
c0 = nextc(p);
if (c0 == -1) return c0;
if (c0 >= 0) --p->column;
list = push(list, nint(c0));
} while(n--);
if (p->pb) {
p->pb = append(list, p->pb);
}
else {
p->pb = list;
}
return c0;
}

static mrb_bool
peek_n(parser_state *p, int c, int n)
{
