#ifndef MRB_NO_STDIO

static void
dump_prefix(node *tree, int offset)
{
printf("%05d ", tree->lineno);
while (offset--) {
putc(' ', stdout);
putc(' ', stdout);
}
}

static void
dump_recur(mrb_state *mrb, node *tree, int offset)
{
while (tree) {
mrb_parser_dump(mrb, tree->car, offset);
tree = tree->cdr;
}
}

static void
dump_args(mrb_state *mrb, node *n, int offset)
{
if (n->car) {
dump_prefix(n, offset+1);
printf("mandatory args:\n");
dump_recur(mrb, n->car, offset+2);
}
n = n->cdr;
if (n->car) {
dump_prefix(n, offset+1);
printf("optional args:\n");
{
node *n2 = n->car;

while (n2) {
dump_prefix(n2, offset+2);
printf("%s=\n", mrb_sym_name(mrb, sym(n2->car->car)));
mrb_parser_dump(mrb, n2->car->cdr, offset+3);
n2 = n2->cdr;
}
}
}
n = n->cdr;
if (n->car) {
mrb_sym rest = sym(n->car);

dump_prefix(n, offset+1);
if (rest == MRB_OPSYM(mul))
printf("rest=*\n");
else
printf("rest=*%s\n", mrb_sym_name(mrb, rest));
}
n = n->cdr;
if (n->car) {
dump_prefix(n, offset+1);
printf("post mandatory args:\n");
dump_recur(mrb, n->car, offset+2);
}

n = n->cdr;
if (n) {
mrb_assert(intn(n->car) == NODE_ARGS_TAIL);
mrb_parser_dump(mrb, n, offset);
}
}

/*
* This function restores the GC arena on return.
* For this reason, if a process that further generates an object is
* performed at the caller, the string pointer returned as the return
* value may become invalid.
*/
static const char*
str_dump(mrb_state *mrb, const char *str, int len)
{
int ai = mrb_gc_arena_save(mrb);
mrb_value s;
# if INT_MAX > MRB_INT_MAX / 4

if (len > MRB_INT_MAX / 4) {
len = MRB_INT_MAX / 4;
}
# endif
s = mrb_str_new(mrb, str, (mrb_int)len);
s = mrb_str_dump(mrb, s);
mrb_gc_arena_restore(mrb, ai);
return RSTRING_PTR(s);
}
#endif

void
mrb_parser_dump(mrb_state *mrb, node *tree, int offset)
{
#ifndef MRB_NO_STDIO
int nodetype;

if (!tree) return;
again:
dump_prefix(tree, offset);
nodetype = intn(tree->car);
tree = tree->cdr;
switch (nodetype) {
case NODE_BEGIN:
printf("NODE_BEGIN:\n");
dump_recur(mrb, tree, offset+1);
break;

case NODE_RESCUE:
printf("NODE_RESCUE:\n");
if (tree->car) {
dump_prefix(tree, offset+1);
printf("body:\n");
mrb_parser_dump(mrb, tree->car, offset+2);
}
tree = tree->cdr;
if (tree->car) {
node *n2 = tree->car;

dump_prefix(n2, offset+1);
printf("rescue:\n");
while (n2) {
node *n3 = n2->car;
if (n3->car) {
dump_prefix(n2, offset+2);
printf("handle classes:\n");
dump_recur(mrb, n3->car, offset+3);
}
if (n3->cdr->car) {
dump_prefix(n3, offset+2);
printf("exc_var:\n");
mrb_parser_dump(mrb, n3->cdr->car, offset+3);
}
if (n3->cdr->cdr->car) {
dump_prefix(n3, offset+2);
printf("rescue body:\n");
mrb_parser_dump(mrb, n3->cdr->cdr->car, offset+3);
}
n2 = n2->cdr;
}
}
tree = tree->cdr;
if (tree->car) {
dump_prefix(tree, offset+1);
printf("else:\n");
mrb_parser_dump(mrb, tree->car, offset+2);
}
break;

case NODE_ENSURE:
printf("NODE_ENSURE:\n");
dump_prefix(tree, offset+1);
printf("body:\n");
mrb_parser_dump(mrb, tree->car, offset+2);
dump_prefix(tree, offset+1);
printf("ensure:\n");
mrb_parser_dump(mrb, tree->cdr->cdr, offset+2);
break;

case NODE_LAMBDA:
printf("NODE_LAMBDA:\n");
dump_prefix(tree, offset);
goto block;

case NODE_BLOCK:
block:
printf("NODE_BLOCK:\n");
tree = tree->cdr;
if (tree->car) {
dump_args(mrb, tree->car, offset+1);
}
dump_prefix(tree, offset+1);
printf("body:\n");
mrb_parser_dump(mrb, tree->cdr->car, offset+2);
break;

case NODE_IF:
printf("NODE_IF:\n");
dump_prefix(tree, offset+1);
printf("cond:\n");
mrb_parser_dump(mrb, tree->car, offset+2);
dump_prefix(tree, offset+1);
printf("then:\n");
mrb_parser_dump(mrb, tree->cdr->car, offset+2);
if (tree->cdr->cdr->car) {
dump_prefix(tree, offset+1);
printf("else:\n");
mrb_parser_dump(mrb, tree->cdr->cdr->car, offset+2);
}
break;

case NODE_AND:
printf("NODE_AND:\n");
mrb_parser_dump(mrb, tree->car, offset+1);
mrb_parser_dump(mrb, tree->cdr, offset+1);
break;

case NODE_OR:
printf("NODE_OR:\n");
mrb_parser_dump(mrb, tree->car, offset+1);
mrb_parser_dump(mrb, tree->cdr, offset+1);
break;

case NODE_CASE:
printf("NODE_CASE:\n");
if (tree->car) {
mrb_parser_dump(mrb, tree->car, offset+1);
}
tree = tree->cdr;
while (tree) {
dump_prefix(tree, offset+1);
printf("case:\n");
dump_recur(mrb, tree->car->car, offset+2);
dump_prefix(tree, offset+1);
printf("body:\n");
mrb_parser_dump(mrb, tree->car->cdr, offset+2);
tree = tree->cdr;
}
break;

case NODE_WHILE:
printf("NODE_WHILE:\n");
dump_prefix(tree, offset+1);
printf("cond:\n");
mrb_parser_dump(mrb, tree->car, offset+2);
dump_prefix(tree, offset+1);
printf("body:\n");
mrb_parser_dump(mrb, tree->cdr, offset+2);
break;

case NODE_UNTIL:
printf("NODE_UNTIL:\n");
dump_prefix(tree, offset+1);
printf("cond:\n");
mrb_parser_dump(mrb, tree->car, offset+2);
dump_prefix(tree, offset+1);
printf("body:\n");
mrb_parser_dump(mrb, tree->cdr, offset+2);
break;

case NODE_FOR:
printf("NODE_FOR:\n");
dump_prefix(tree, offset+1);
printf("var:\n");
{
node *n2 = tree->car;

if (n2->car) {
dump_prefix(n2, offset+2);
printf("pre:\n");
dump_recur(mrb, n2->car, offset+3);
}
n2 = n2->cdr;
if (n2) {
if (n2->car) {
dump_prefix(n2, offset+2);
printf("rest:\n");
mrb_parser_dump(mrb, n2->car, offset+3);
}
n2 = n2->cdr;
if (n2) {
if (n2->car) {
dump_prefix(n2, offset+2);
printf("post:\n");
dump_recur(mrb, n2->car, offset+3);
}
}
}
}
tree = tree->cdr;
dump_prefix(tree, offset+1);
printf("in:\n");
mrb_parser_dump(mrb, tree->car, offset+2);
tree = tree->cdr;
dump_prefix(tree, offset+1);
printf("do:\n");
mrb_parser_dump(mrb, tree->car, offset+2);
break;

case NODE_SCOPE:
printf("NODE_SCOPE:\n");
{
node *n2 = tree->car;
mrb_bool first_lval = TRUE;

if (n2 && (n2->car || n2->cdr)) {
dump_prefix(n2, offset+1);
printf("local variables:\n");
dump_prefix(n2, offset+2);
while (n2) {
if (n2->car) {
if (!first_lval) printf(", ");
printf("%s", mrb_sym_name(mrb, sym(n2->car)));
first_lval = FALSE;
}
n2 = n2->cdr;
}
printf("\n");
}
}
tree = tree->cdr;
offset++;
goto again;

case NODE_FCALL:
case NODE_CALL:
case NODE_SCALL:
switch (nodetype) {
case NODE_FCALL:
printf("NODE_FCALL:\n"); break;
case NODE_CALL:
printf("NODE_CALL(.):\n"); break;
case NODE_SCALL:
printf("NODE_SCALL(&.):\n"); break;
default:
break;
}
mrb_parser_dump(mrb, tree->car, offset+1);
dump_prefix(tree, offset+1);
printf("method='%s' (%d)\n",
mrb_sym_dump(mrb, sym(tree->cdr->car)),
intn(tree->cdr->car));
tree = tree->cdr->cdr->car;
if (tree) {
dump_prefix(tree, offset+1);
printf("args:\n");
dump_recur(mrb, tree->car, offset+2);
if (tree->cdr) {
if (tree->cdr->car) {
dump_prefix(tree, offset+1);
printf("kwargs:\n");
mrb_parser_dump(mrb, tree->cdr->car, offset+2);
}
if (tree->cdr->cdr) {
dump_prefix(tree, offset+1);
printf("block:\n");
mrb_parser_dump(mrb, tree->cdr->cdr, offset+2);
}
}
}
break;

case NODE_DOT2:
printf("NODE_DOT2:\n");
mrb_parser_dump(mrb, tree->car, offset+1);
mrb_parser_dump(mrb, tree->cdr, offset+1);
break;

case NODE_DOT3:
printf("NODE_DOT3:\n");
mrb_parser_dump(mrb, tree->car, offset+1);
mrb_parser_dump(mrb, tree->cdr, offset+1);
break;

case NODE_COLON2:
printf("NODE_COLON2:\n");
mrb_parser_dump(mrb, tree->car, offset+1);
dump_prefix(tree, offset+1);
printf("::%s\n", mrb_sym_name(mrb, sym(tree->cdr)));
break;

case NODE_COLON3:
printf("NODE_COLON3: ::%s\n", mrb_sym_name(mrb, sym(tree)));
break;

case NODE_ARRAY:
printf("NODE_ARRAY:\n");
dump_recur(mrb, tree, offset+1);
break;

case NODE_HASH:
printf("NODE_HASH:\n");
while (tree) {
dump_prefix(tree, offset+1);
printf("key:\n");
mrb_parser_dump(mrb, tree->car->car, offset+2);
dump_prefix(tree, offset+1);
printf("value:\n");
mrb_parser_dump(mrb, tree->car->cdr, offset+2);
tree = tree->cdr;
}
break;

case NODE_KW_HASH:
printf("NODE_KW_HASH:\n");
while (tree) {
dump_prefix(tree, offset+1);
printf("key:\n");
mrb_parser_dump(mrb, tree->car->car, offset+2);
dump_prefix(tree, offset+1);
printf("value:\n");
mrb_parser_dump(mrb, tree->car->cdr, offset+2);
tree = tree->cdr;
}
break;

case NODE_SPLAT:
printf("NODE_SPLAT:\n");
mrb_parser_dump(mrb, tree, offset+1);
break;

case NODE_ASGN:
printf("NODE_ASGN:\n");
dump_prefix(tree, offset+1);
printf("lhs:\n");
mrb_parser_dump(mrb, tree->car, offset+2);
dump_prefix(tree, offset+1);
printf("rhs:\n");
mrb_parser_dump(mrb, tree->cdr, offset+2);
break;

case NODE_MASGN:
printf("NODE_MASGN:\n");
dump_prefix(tree, offset+1);
printf("mlhs:\n");
{
node *n2 = tree->car;

if (n2->car) {
dump_prefix(tree, offset+2);
printf("pre:\n");
dump_recur(mrb, n2->car, offset+3);
}
n2 = n2->cdr;
if (n2) {
if (n2->car) {
dump_prefix(n2, offset+2);
printf("rest:\n");
if (n2->car == nint(-1)) {
dump_prefix(n2, offset+2);
printf("(empty)\n");
}
else {
mrb_parser_dump(mrb, n2->car, offset+3);
}
}
n2 = n2->cdr;
if (n2 && n2->car) {
dump_prefix(n2, offset+2);
printf("post:\n");
dump_recur(mrb, n2->car, offset+3);
}
}
}
dump_prefix(tree, offset+1);
printf("rhs:\n");
mrb_parser_dump(mrb, tree->cdr, offset+2);
break;

case NODE_OP_ASGN:
printf("NODE_OP_ASGN:\n");
dump_prefix(tree, offset+1);
printf("lhs:\n");
mrb_parser_dump(mrb, tree->car, offset+2);
tree = tree->cdr;
dump_prefix(tree, offset+1);
printf("op='%s' (%d)\n", mrb_sym_name(mrb, sym(tree->car)), intn(tree->car));
tree = tree->cdr;
mrb_parser_dump(mrb, tree->car, offset+1);
break;

case NODE_SUPER:
printf("NODE_SUPER:\n");
if (tree) {
dump_prefix(tree, offset+1);
printf("args:\n");
dump_recur(mrb, tree->car, offset+2);
if (tree->cdr) {
dump_prefix(tree, offset+1);
printf("block:\n");
mrb_parser_dump(mrb, tree->cdr, offset+2);
}
}
break;

case NODE_ZSUPER:
printf("NODE_ZSUPER:\n");
if (tree) {
dump_prefix(tree, offset+1);
printf("args:\n");
dump_recur(mrb, tree->car, offset+2);
if (tree->cdr) {
dump_prefix(tree, offset+1);
printf("block:\n");
mrb_parser_dump(mrb, tree->cdr, offset+2);
}
}
break;

case NODE_RETURN:
printf("NODE_RETURN:\n");
mrb_parser_dump(mrb, tree, offset+1);
break;

case NODE_YIELD:
printf("NODE_YIELD:\n");
dump_recur(mrb, tree, offset+1);
break;

case NODE_BREAK:
printf("NODE_BREAK:\n");
mrb_parser_dump(mrb, tree, offset+1);
break;

case NODE_NEXT:
printf("NODE_NEXT:\n");
mrb_parser_dump(mrb, tree, offset+1);
break;

case NODE_REDO:
printf("NODE_REDO\n");
break;

case NODE_RETRY:
printf("NODE_RETRY\n");
break;

case NODE_LVAR:
printf("NODE_LVAR %s\n", mrb_sym_name(mrb, sym(tree)));
break;

case NODE_GVAR:
printf("NODE_GVAR %s\n", mrb_sym_name(mrb, sym(tree)));
break;

case NODE_IVAR:
printf("NODE_IVAR %s\n", mrb_sym_name(mrb, sym(tree)));
break;

case NODE_CVAR:
printf("NODE_CVAR %s\n", mrb_sym_name(mrb, sym(tree)));
break;

case NODE_NVAR:
printf("NODE_NVAR %d\n", intn(tree));
break;

case NODE_CONST:
printf("NODE_CONST %s\n", mrb_sym_name(mrb, sym(tree)));
break;

case NODE_MATCH:
printf("NODE_MATCH:\n");
dump_prefix(tree, offset + 1);
printf("lhs:\n");
mrb_parser_dump(mrb, tree->car, offset + 2);
dump_prefix(tree, offset + 1);
printf("rhs:\n");
mrb_parser_dump(mrb, tree->cdr, offset + 2);
break;

case NODE_BACK_REF:
printf("NODE_BACK_REF: $%c\n", intn(tree));
break;

case NODE_NTH_REF:
printf("NODE_NTH_REF: $%d\n", intn(tree));
break;

case NODE_ARG:
printf("NODE_ARG %s\n", mrb_sym_name(mrb, sym(tree)));
break;

case NODE_BLOCK_ARG:
printf("NODE_BLOCK_ARG:\n");
mrb_parser_dump(mrb, tree, offset+1);
break;

case NODE_INT:
printf("NODE_INT %s base %d\n", (char*)tree->car, intn(tree->cdr->car));
break;

case NODE_FLOAT:
printf("NODE_FLOAT %s\n", (char*)tree);
break;

case NODE_NEGATE:
printf("NODE_NEGATE:\n");
mrb_parser_dump(mrb, tree, offset+1);
break;

case NODE_STR:
printf("NODE_STR %s len %d\n", str_dump(mrb, (char*)tree->car, intn(tree->cdr)), intn(tree->cdr));
break;

case NODE_DSTR:
printf("NODE_DSTR:\n");
dump_recur(mrb, tree, offset+1);
break;

case NODE_XSTR:
printf("NODE_XSTR %s len %d\n", str_dump(mrb, (char*)tree->car, intn(tree->cdr)), intn(tree->cdr));
break;

case NODE_DXSTR:
printf("NODE_DXSTR:\n");
dump_recur(mrb, tree, offset+1);
break;

case NODE_REGX:
printf("NODE_REGX /%s/\n", (char*)tree->car);
if (tree->cdr->car) {
dump_prefix(tree, offset+1);
printf("opt: %s\n", (char*)tree->cdr->car);
}
if (tree->cdr->cdr) {
dump_prefix(tree, offset+1);
printf("enc: %s\n", (char*)tree->cdr->cdr);
}
break;

case NODE_DREGX:
printf("NODE_DREGX:\n");
dump_recur(mrb, tree->car, offset+1);
dump_prefix(tree, offset+1);
printf("tail: %s\n", (char*)tree->cdr->cdr->car);
if (tree->cdr->cdr->cdr->car) {
dump_prefix(tree, offset+1);
printf("opt: %s\n", (char*)tree->cdr->cdr->cdr->car);
}
if (tree->cdr->cdr->cdr->cdr) {
dump_prefix(tree, offset+1);
printf("enc: %s\n", (char*)tree->cdr->cdr->cdr->cdr);
}
break;

case NODE_SYM:
printf("NODE_SYM :%s (%d)\n", mrb_sym_dump(mrb, sym(tree)),
intn(tree));
break;

case NODE_DSYM:
printf("NODE_DSYM:\n");
mrb_parser_dump(mrb, tree, offset+1);
break;

case NODE_WORDS:
printf("NODE_WORDS:\n");
dump_recur(mrb, tree, offset+1);
break;

case NODE_SYMBOLS:
printf("NODE_SYMBOLS:\n");
dump_recur(mrb, tree, offset+1);
break;

case NODE_LITERAL_DELIM:
printf("NODE_LITERAL_DELIM\n");
break;

case NODE_SELF:
printf("NODE_SELF\n");
break;

case NODE_NIL:
printf("NODE_NIL\n");
break;

case NODE_TRUE:
printf("NODE_TRUE\n");
break;

case NODE_FALSE:
printf("NODE_FALSE\n");
break;

case NODE_ALIAS:
printf("NODE_ALIAS %s %s:\n",
mrb_sym_dump(mrb, sym(tree->car)),
mrb_sym_dump(mrb, sym(tree->cdr)));
break;

case NODE_UNDEF:
printf("NODE_UNDEF");
{
node *t = tree;
while (t) {
printf(" %s", mrb_sym_dump(mrb, sym(t->car)));
t = t->cdr;
}
}
printf(":\n");
break;

case NODE_CLASS:
printf("NODE_CLASS:\n");
if (tree->car->car == nint(0)) {
dump_prefix(tree, offset+1);
printf(":%s\n", mrb_sym_name(mrb, sym(tree->car->cdr)));
}
else if (tree->car->car == nint(1)) {
dump_prefix(tree, offset+1);
printf("::%s\n", mrb_sym_name(mrb, sym(tree->car->cdr)));
}
else {
mrb_parser_dump(mrb, tree->car->car, offset+1);
dump_prefix(tree, offset+1);
printf("::%s\n", mrb_sym_name(mrb, sym(tree->car->cdr)));
}
if (tree->cdr->car) {
dump_prefix(tree, offset+1);
printf("super:\n");
mrb_parser_dump(mrb, tree->cdr->car, offset+2);
}
dump_prefix(tree, offset+1);
printf("body:\n");
mrb_parser_dump(mrb, tree->cdr->cdr->car->cdr, offset+2);
break;

case NODE_MODULE:
printf("NODE_MODULE:\n");
if (tree->car->car == nint(0)) {
dump_prefix(tree, offset+1);
printf(":%s\n", mrb_sym_name(mrb, sym(tree->car->cdr)));
}
else if (tree->car->car == nint(1)) {
dump_prefix(tree, offset+1);
printf("::%s\n", mrb_sym_name(mrb, sym(tree->car->cdr)));
}
else {
mrb_parser_dump(mrb, tree->car->car, offset+1);
dump_prefix(tree, offset+1);
printf("::%s\n", mrb_sym_name(mrb, sym(tree->car->cdr)));
}
dump_prefix(tree, offset+1);
printf("body:\n");
mrb_parser_dump(mrb, tree->cdr->car->cdr, offset+2);
break;

case NODE_SCLASS:
printf("NODE_SCLASS:\n");
mrb_parser_dump(mrb, tree->car, offset+1);
dump_prefix(tree, offset+1);
printf("body:\n");
mrb_parser_dump(mrb, tree->cdr->car->cdr, offset+2);
break;

case NODE_DEF:
printf("NODE_DEF:\n");
dump_prefix(tree, offset+1);
printf("%s\n", mrb_sym_dump(mrb, sym(tree->car)));
tree = tree->cdr;
{
node *n2 = tree->car;
mrb_bool first_lval = TRUE;

if (n2 && (n2->car || n2->cdr)) {
dump_prefix(n2, offset+1);
printf("local variables:\n");
dump_prefix(n2, offset+2);
while (n2) {
if (n2->car) {
if (!first_lval) printf(", ");
printf("%s", mrb_sym_name(mrb, sym(n2->car)));
first_lval = FALSE;
}
n2 = n2->cdr;
}
printf("\n");
}
}
tree = tree->cdr;
if (tree->car) {
dump_args(mrb, tree->car, offset);
}
mrb_parser_dump(mrb, tree->cdr->car, offset+1);
break;

case NODE_SDEF:
printf("NODE_SDEF:\n");
mrb_parser_dump(mrb, tree->car, offset+1);
tree = tree->cdr;
dump_prefix(tree, offset+1);
printf(":%s\n", mrb_sym_dump(mrb, sym(tree->car)));
tree = tree->cdr->cdr;
if (tree->car) {
dump_args(mrb, tree->car, offset+1);
}
tree = tree->cdr;
mrb_parser_dump(mrb, tree->car, offset+1);
break;

case NODE_POSTEXE:
printf("NODE_POSTEXE:\n");
mrb_parser_dump(mrb, tree, offset+1);
break;

case NODE_HEREDOC:
printf("NODE_HEREDOC (<<%s):\n", ((parser_heredoc_info*)tree)->term);
dump_recur(mrb, ((parser_heredoc_info*)tree)->doc, offset+1);
break;

case NODE_ARGS_TAIL:
printf("NODE_ARGS_TAIL:\n");
{
node *kws = tree->car;

while (kws) {
mrb_parser_dump(mrb, kws->car, offset+1);
kws = kws->cdr;
}
}
tree = tree->cdr;
if (tree->car) {
mrb_assert(intn(tree->car->car) == NODE_KW_REST_ARGS);
mrb_parser_dump(mrb, tree->car, offset+1);
}
tree = tree->cdr;
if (tree->car) {
dump_prefix(tree, offset+1);
printf("block='%s'\n", mrb_sym_name(mrb, sym(tree->car)));
}
break;

case NODE_KW_ARG:
printf("NODE_KW_ARG %s:\n", mrb_sym_name(mrb, sym(tree->car)));
mrb_parser_dump(mrb, tree->cdr->car, offset + 1);
break;

case NODE_KW_REST_ARGS:
if (tree)
printf("NODE_KW_REST_ARGS %s\n", mrb_sym_name(mrb, sym(tree)));
else
printf("NODE_KW_REST_ARGS\n");
break;

default:
printf("node type: %d (0x%x)\n", nodetype, (unsigned)nodetype);
break;
}
#endif
}

typedef mrb_bool mrb_parser_foreach_top_variable_func(mrb_state *mrb, mrb_sym sym, void *user);
void mrb_parser_foreach_top_variable(mrb_state *mrb, struct mrb_parser_state *p, mrb_parser_foreach_top_variable_func *func, void *user);

void
mrb_parser_foreach_top_variable(mrb_state *mrb, struct mrb_parser_state *p, mrb_parser_foreach_top_variable_func *func, void *user)
{
const mrb_ast_node *n = p->tree;
if ((intptr_t)n->car == NODE_SCOPE) {
n = n->cdr->car;
for (; n; n = n->cdr) {
mrb_sym sym = sym(n->car);
if (sym && !func(mrb, sym, user)) break;
}
}
